    note_volume: '1 L = 1000 mL = 1000 cm³, અને 1 m³ = 1000 L. તેથી 1 m × 1 m × 1 m ની ટાંકીમાં 1000 લિટર પાણી સમાય.',
    note_speed: 'ઝડપ = અંતર ÷ સમય. 60 km/h ની ઝડપ મર્યાદા એટલે આશરે 16.7 m/s. હવામાં અવાજ આશરે 343 m/s ની ઝડપે જાય છે.',
    note_data: '1 બાઇટ = 8 બિટ. 128 GB ની પેન-ડ્રાઇવ Windows કમ્પ્યુટર પર આશરે 119 GB જ દેખાય છે, કારણ કે કંપની 1000 ના હિસાબે ગણે છે અને Windows 1024 ના હિસાબે.',
    note_pressure: 'દરિયાની સપાટીએ હવાનું દબાણ આશરે 1 atm = 101.325 kPa = 760 mmHg હોય છે. હવામાન સમાચારમાં hPa, ડૉક્ટર બ્લડ પ્રેશર માટે mmHg અને ટાયર માટે psi વપરાય છે.',
