    speed_trick_title: '5/18 உத்தி',
    speed_trick: '1 km/h = 1000 m ÷ 3600 s = 5/18 m/s. எனவே km/h → m/s க்கு 5/18 ஆல் பெருக்குங்கள்; m/s → km/h க்கு 18/5 ஆல் பெருக்குங்கள்.',
    temp_formulas_title: 'வெப்பநிலைச் சூத்திரங்கள்',
    data_note: 'கிலோபைட் இரண்டு வகை: போன், பென்-டிரைவ் தயாரிப்பாளர்கள் 1 KB = 1000 பைட் எனக் கொள்கிறார்கள். 1 KiB = 1024 பைட்டைப் பல பள்ளிப் புத்தகங்களும் Windows-உம் நேரடியாக “KB” என்கின்றன.',
    area_note: 'பிகா, பிஸ்வா, கனால், மர்லா போன்ற நில அலகுகள் மாநிலத்துக்கு மாநிலம் வேறுபடுகின்றன, எனவே அவை இங்கே இல்லை. அவற்றுக்கு உங்கள் மாநில நிலப் பதிவேடுகளைப் பாருங்கள்.',
    try_title: 'ஓர் எடுத்துக்காட்டை முயலுங்கள்',
    did_you_know: 'உங்களுக்குத் தெரியுமா?',
    all_units_title: 'இதே மதிப்பு எல்லா அலகுகளிலும்',
    all_units_hint: 'ஒரு வரிசையைத் தட்டினால் அந்த அலகுக்கு மாறும்.',
    unit_col: 'அலகு', value_col: 'மதிப்பு',
    note_length: '1 km = 1000 m, 1 m = 100 cm, 1 cm = 10 mm. கிரிக்கெட் ஆடுகளம் 22 கெஜம் நீளம், அதாவது சுமார் 20.12 m.',
    note_mass: '1 குவிண்டால் = 100 kg (தானியச் சந்தையில் பயன்படும்), 1 டன் = 1000 kg. ரத்தினங்கள் காரட்டில் (0.2 g) எடை போடப்படுகின்றன; பழைய தோலா சுமார் 11.66 g.',
    note_time: '1 மணி = 60 நிமிடம் = 3600 வினாடி, 1 நாள் = 86,400 வினாடி. இங்கே 1 ஆண்டு 365 நாள் எனக் கொள்ளப்படுகிறது (நெட்டாண்டில் 366 நாள்).',
    note_temp: 'நீர் 0 °C (32 °F, 273.15 K) இல் உறைகிறது, 100 °C (212 °F) இல் கொதிக்கிறது. உடலின் இயல்பு வெப்பநிலை சுமார் 37 °C (98.6 °F).',
    note_area: '1 ஹெக்டேர் என்பது 100 m × 100 m சதுரம் = 10,000 m², சுமார் 2.47 ஏக்கர். 1 ஏக்கர் = 100 சென்ட் = 40 குண்டா, 1 கஜம் = 1 சதுர கெஜம்.',
    note_volume: '1 L = 1000 mL = 1000 cm³, 1 m³ = 1000 L. எனவே 1 m × 1 m × 1 m தொட்டியில் 1000 லிட்டர் நீர் கொள்ளும்.',
    note_speed: 'வேகம் = தொலைவு ÷ நேரம். 60 km/h வேக வரம்பு சுமார் 16.7 m/s. காற்றில் ஒலி சுமார் 343 m/s வேகத்தில் செல்கிறது.',
    note_data: '1 பைட் = 8 பிட். 128 GB பென்-டிரைவ் Windows கணினியில் சுமார் 119 GB மட்டுமே காட்டும்; தயாரிப்பாளர் 1000 கணக்கில் எண்ணுகிறார், Windows 1024 கணக்கில் எண்ணுகிறது.',
    note_pressure: 'கடல் மட்டத்தில் காற்றழுத்தம் சுமார் 1 atm = 101.325 kPa = 760 mmHg. வானிலை அறிக்கைகள் hPa, இரத்த அழுத்தத்துக்கு மருத்துவர்கள் mmHg, டயர்களுக்கு psi பயன்படுத்துகிறார்கள்.',
    note_energy: 'மின் கட்டணத்தில் 1 “யூனிட்” = 1 kWh = 36,00,000 J. உணவுப் பொட்டலங்களில் உள்ள “Calorie” உண்மையில் கிலோகலோரி (kcal) = 4.184 kJ.',
