    w_thousand: 'ஆயிரம்', w_lakh: 'லட்சம்', w_crore: 'கோடி', w_million: 'மில்லியன்', w_billion: 'பில்லியன்', w_trillion: 'டிரில்லியன்',
    help_title: 'எப்படிப் பயன்படுத்துவது / வகுப்பறைக்கான யோசனைகள்',
    help_1: 'எதை மாற்றுவது எனத் தேர்ந்தெடுத்து, இரண்டு அலகுகளைத் தேர்ந்து, எந்தப் பெட்டியிலும் எண்ணை எழுதுங்கள். மற்றப் பெட்டி உடனே மாறும்.',
    help_2: '“படிப்படியாக” படியுங்கள்: பெரிய அலகிலிருந்து சிறிய அலகுக்கு எண் பெரிதாகும் (பெருக்கல்); சிறிய அலகிலிருந்து பெரிய அலகுக்கு எண் சிறிதாகும் (வகுத்தல்).',
    help_3: 'அலகுகளை இடம் மாற்ற ⇄ அழுத்துங்கள். அட்டவணையில் இதே மதிப்பு எல்லா அலகுகளிலும் தெரியும்; ஒரு வரிசையைத் தட்டி அந்த அலகைத் தேர்ந்தெடுங்கள்.',
    help_4: 'எண்கள் தாவலில் எந்த முழு எண்ணையும் எழுதுங்கள்: இந்திய, பன்னாட்டுக் காற்புள்ளிகள், சொற்களில் எண், இடமதிப்பு அட்டவணை, விரிவாக்க வடிவம் ஆகியவற்றைப் பாருங்கள்.',
    help_5: 'வகுப்புச் செயல்பாடு: வினாடி-வினா முறையை இயக்கி “ஏதாவது ஓர் எண்” அழுத்துங்கள். அணிகள் அந்த எண்ணை இரண்டு முறைகளிலும் சொற்களில் எழுதட்டும்; பின் “விடையைக் காட்டு” மூலம் சரிபாருங்கள்.',
    help_6: 'பயிற்சி தாவல்: சிறு கேள்விகளுக்கு விடை எழுதுங்கள் (தவறினால் படிகள் தெரியும்) அல்லது 10 கேள்விப் பயிற்சித்தாளை அச்சிடுங்கள். தெளிவான தாளுக்கு அச்சிடுங்கள்; ஸ்மார்ட்போர்டில் முழுத் திரையைப் பயன்படுத்துங்கள்.',
    u_ang: 'ஆங்ஸ்ட்ராம்', u_au: 'வானியல் அலகு', u_ly: 'ஒளியாண்டு',
