    hint_smaller: 'చిన్న ప్రమాణం → పెద్ద ప్రమాణం, కాబట్టి సంఖ్య చిన్నదవుతుంది.',
    hint_same: 'రెండు ప్రమాణాలూ ఒకే పరిమాణం, కాబట్టి సంఖ్య మారదు.',
    speed_trick_title: '5/18 చిట్కా',
    speed_trick: '1 km/h = 1000 m ÷ 3600 s = 5/18 m/s. కాబట్టి km/h → m/s కోసం 5/18 తో గుణించండి, m/s → km/h కోసం 18/5 తో గుణించండి.',
    temp_formulas_title: 'ఉష్ణోగ్రత సూత్రాలు',
    data_note: 'కిలోబైట్‌లు రెండు రకాలు: ఫోన్, పెన్-డ్రైవ్ తయారీదారులు 1 KB = 1000 బైట్‌లు అని లెక్కిస్తారు. 1 KiB = 1024 బైట్‌లను చాలా పాఠ్యపుస్తకాలు, Windows నేరుగా “KB” అంటాయి.',
    area_note: 'బిఘా, బిస్వా, కనాల్, మర్లా వంటి భూమి ప్రమాణాలు రాష్ట్రాన్ని బట్టి మారుతాయి, కాబట్టి ఇక్కడ ఇవ్వలేదు. వాటి కోసం మీ రాష్ట్ర భూ రికార్డులు చూడండి.',
    try_title: 'ఒక ఉదాహరణ ప్రయత్నించండి',
    did_you_know: 'మీకు తెలుసా?',
    all_units_title: 'ఇదే విలువ అన్ని ప్రమాణాల్లో',
    all_units_hint: 'ఏదైనా వరుసను తాకితే ఆ ప్రమాణంలోకి మారుతుంది.',
    unit_col: 'ప్రమాణం', value_col: 'విలువ',
    note_length: '1 km = 1000 m, 1 m = 100 cm, 1 cm = 10 mm. క్రికెట్ పిచ్ పొడవు 22 గజాలు, అంటే సుమారు 20.12 m.',
    note_mass: '1 క్వింటాలు = 100 kg (ధాన్యం మార్కెట్లలో వాడతారు), 1 టన్ను = 1000 kg. రత్నాలను క్యారెట్‌లో (0.2 g) తూస్తారు; పాత తులం సుమారు 11.66 g.',
    note_time: '1 గంట = 60 నిమిషాలు = 3600 సెకన్లు, 1 రోజు = 86,400 సెకన్లు. ఇక్కడ 1 సంవత్సరం 365 రోజులుగా తీసుకున్నాం (లీపు సంవత్సరంలో 366 రోజులు).',
    note_temp: 'నీరు 0 °C (32 °F, 273.15 K) వద్ద గడ్డకడుతుంది, 100 °C (212 °F) వద్ద మరుగుతుంది. శరీర సాధారణ ఉష్ణోగ్రత సుమారు 37 °C (98.6 °F).',
    note_area: '1 హెక్టారు అంటే 100 m × 100 m చతురస్రం = 10,000 m², సుమారు 2.47 ఎకరాలు. 1 ఎకరం = 100 సెంట్లు = 40 గుంటలు, 1 గజం = 1 చదరపు గజం.',
    note_volume: '1 L = 1000 mL = 1000 cm³, 1 m³ = 1000 L. కాబట్టి 1 m × 1 m × 1 m ట్యాంకులో 1000 లీటర్ల నీరు పడుతుంది.',
    note_speed: 'వేగం = దూరం ÷ కాలం. 60 km/h వేగ పరిమితి సుమారు 16.7 m/s. గాలిలో ధ్వని సుమారు 343 m/s వేగంతో ప్రయాణిస్తుంది.',
    note_data: '1 బైట్ = 8 బిట్‌లు. 128 GB పెన్-డ్రైవ్ Windows కంప్యూటర్‌లో సుమారు 119 GB మాత్రమే చూపిస్తుంది; తయారీదారు 1000 లెక్కన, Windows 1024 లెక్కన లెక్కిస్తాయి.',
    note_pressure: 'సముద్ర మట్టం వద్ద గాలి పీడనం సుమారు 1 atm = 101.325 kPa = 760 mmHg. వాతావరణ వార్తల్లో hPa, రక్తపోటుకు డాక్టర్లు mmHg, టైర్లకు psi వాడతారు.',
