    help_1: 'ఏది మార్చాలో ఎంచుకుని, రెండు ప్రమాణాలను ఎంచుకుని, ఏ పెట్టెలోనైనా సంఖ్య రాయండి. రెండో పెట్టె వెంటనే మారుతుంది.',
    help_2: '“దశలవారీగా” చదవండి: పెద్ద ప్రమాణం నుంచి చిన్న ప్రమాణానికి సంఖ్య పెద్దదవుతుంది (గుణకారం); చిన్న నుంచి పెద్ద ప్రమాణానికి సంఖ్య చిన్నదవుతుంది (భాగహారం).',
