    help_5: 'తరగతి కార్యకలాపం: క్విజ్ మోడ్ ఆన్ చేసి “ఏదో ఒక సంఖ్య” నొక్కండి. జట్లు ఆ సంఖ్యను రెండు పద్ధతుల్లో పదాల్లో రాయాలి; తర్వాత “జవాబు చూపించు” నొక్కి సరిచూడండి.',
