    data_note: 'ಕಿಲೋಬೈಟ್ ಎರಡು ಬಗೆ: ಫೋನ್ ಮತ್ತು ಪೆನ್-ಡ್ರೈವ್ ತಯಾರಕರು 1 KB = 1000 ಬೈಟ್ ಎಂದು ಎಣಿಸುತ್ತಾರೆ. 1 KiB = 1024 ಬೈಟ್ ಅನ್ನು ಅನೇಕ ಶಾಲಾ ಪುಸ್ತಕಗಳು ಮತ್ತು Windows ನೇರವಾಗಿ “KB” ಎನ್ನುತ್ತವೆ.',
    area_note: 'ಬಿಘಾ, ಬಿಸ್ವಾ, ಕನಾಲ್, ಮರ್ಲಾ ಮುಂತಾದ ಭೂಮಿ ಏಕಮಾನಗಳು ರಾಜ್ಯದಿಂದ ರಾಜ್ಯಕ್ಕೆ ಬೇರೆ ಬೇರೆ ಅಳತೆಯವು, ಆದ್ದರಿಂದ ಇಲ್ಲಿ ಕೊಟ್ಟಿಲ್ಲ. ಅವುಗಳಿಗೆ ನಿಮ್ಮ ರಾಜ್ಯದ ಭೂ ದಾಖಲೆಗಳನ್ನು ನೋಡಿ.',
    try_title: 'ಒಂದು ಉದಾಹರಣೆ ಪ್ರಯತ್ನಿಸಿ',
    did_you_know: 'ನಿಮಗೆ ಗೊತ್ತೇ?',
    all_units_title: 'ಇದೇ ಬೆಲೆ ಎಲ್ಲಾ ಏಕಮಾನಗಳಲ್ಲಿ',
    all_units_hint: 'ಯಾವುದಾದರೂ ಸಾಲನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ ಆ ಏಕಮಾನಕ್ಕೆ ಬದಲಿಸಿ.',
    unit_col: 'ಏಕಮಾನ', value_col: 'ಬೆಲೆ',
    note_length: '1 km = 1000 m, 1 m = 100 cm ಮತ್ತು 1 cm = 10 mm. ಕ್ರಿಕೆಟ್ ಪಿಚ್ 22 ಗಜ ಉದ್ದ, ಅಂದರೆ ಸುಮಾರು 20.12 m.',
    note_mass: '1 ಕ್ವಿಂಟಲ್ = 100 kg (ಧಾನ್ಯ ಮಾರುಕಟ್ಟೆಯಲ್ಲಿ ಬಳಸುತ್ತಾರೆ) ಮತ್ತು 1 ಟನ್ = 1000 kg. ರತ್ನಗಳನ್ನು ಕ್ಯಾರೆಟ್‌ನಲ್ಲಿ (0.2 g) ತೂಗುತ್ತಾರೆ; ಹಳೆಯ ತೊಲ ಸುಮಾರು 11.66 g.',
    note_time: '1 ಗಂಟೆ = 60 ನಿಮಿಷ = 3600 ಸೆಕೆಂಡ್, 1 ದಿನ = 86,400 ಸೆಕೆಂಡ್. ಇಲ್ಲಿ 1 ವರ್ಷವನ್ನು 365 ದಿನ ಎಂದು ತೆಗೆದುಕೊಳ್ಳಲಾಗಿದೆ (ಅಧಿಕ ವರ್ಷದಲ್ಲಿ 366 ದಿನ).',
    note_temp: 'ನೀರು 0 °C (32 °F, 273.15 K) ನಲ್ಲಿ ಹೆಪ್ಪುಗಟ್ಟುತ್ತದೆ ಮತ್ತು 100 °C (212 °F) ನಲ್ಲಿ ಕುದಿಯುತ್ತದೆ. ದೇಹದ ಸಾಮಾನ್ಯ ತಾಪಮಾನ ಸುಮಾರು 37 °C (98.6 °F).',
    note_area: '1 ಹೆಕ್ಟೇರ್ ಎಂದರೆ 100 m × 100 m ಚೌಕ = 10,000 m², ಸುಮಾರು 2.47 ಎಕರೆ. 1 ಎಕರೆ = 100 ಸೆಂಟ್ = 40 ಗುಂಟೆ, ಮತ್ತು 1 ಗಜ = 1 ಚದರ ಗಜ.',
    note_volume: '1 L = 1000 mL = 1000 cm³, ಮತ್ತು 1 m³ = 1000 L. ಆದ್ದರಿಂದ 1 m × 1 m × 1 m ಟ್ಯಾಂಕ್‌ನಲ್ಲಿ 1000 ಲೀಟರ್ ನೀರು ಹಿಡಿಯುತ್ತದೆ.',
    note_speed: 'ವೇಗ = ದೂರ ÷ ಸಮಯ. 60 km/h ವೇಗ ಮಿತಿ ಸುಮಾರು 16.7 m/s. ಗಾಳಿಯಲ್ಲಿ ಶಬ್ದ ಸುಮಾರು 343 m/s ವೇಗದಲ್ಲಿ ಚಲಿಸುತ್ತದೆ.',
    note_data: '1 ಬೈಟ್ = 8 ಬಿಟ್. 128 GB ಪೆನ್-ಡ್ರೈವ್ Windows ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಸುಮಾರು 119 GB ಮಾತ್ರ ತೋರಿಸುತ್ತದೆ; ತಯಾರಕರು 1000 ಲೆಕ್ಕದಲ್ಲಿ, Windows 1024 ಲೆಕ್ಕದಲ್ಲಿ ಎಣಿಸುತ್ತವೆ.',
    note_pressure: 'ಸಮುದ್ರ ಮಟ್ಟದಲ್ಲಿ ಗಾಳಿಯ ಒತ್ತಡ ಸುಮಾರು 1 atm = 101.325 kPa = 760 mmHg. ಹವಾಮಾನ ವರದಿಗಳಲ್ಲಿ hPa, ರಕ್ತದೊತ್ತಡಕ್ಕೆ ವೈದ್ಯರು mmHg ಮತ್ತು ಟೈರ್‌ಗಳಿಗೆ psi ಬಳಸುತ್ತಾರೆ.',
