    help_1: 'ಏನನ್ನು ಬದಲಿಸಬೇಕು ಆರಿಸಿ, ಎರಡು ಏಕಮಾನಗಳನ್ನು ಆರಿಸಿ ಮತ್ತು ಯಾವುದೇ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ ಸಂಖ್ಯೆ ಬರೆಯಿರಿ. ಇನ್ನೊಂದು ಪೆಟ್ಟಿಗೆ ತಕ್ಷಣ ಬದಲಾಗುತ್ತದೆ.',
    help_2: '“ಹಂತ ಹಂತವಾಗಿ” ಓದಿ: ದೊಡ್ಡ ಏಕಮಾನದಿಂದ ಚಿಕ್ಕ ಏಕಮಾನಕ್ಕೆ ಸಂಖ್ಯೆ ದೊಡ್ಡದಾಗುತ್ತದೆ (ಗುಣಾಕಾರ); ಚಿಕ್ಕದರಿಂದ ದೊಡ್ಡ ಏಕಮಾನಕ್ಕೆ ಸಂಖ್ಯೆ ಚಿಕ್ಕದಾಗುತ್ತದೆ (ಭಾಗಾಕಾರ).',
    help_3: 'ಏಕಮಾನಗಳನ್ನು ಅದಲುಬದಲು ಮಾಡಲು ⇄ ಒತ್ತಿ. ಕೋಷ್ಟಕದಲ್ಲಿ ಇದೇ ಬೆಲೆ ಎಲ್ಲಾ ಏಕಮಾನಗಳಲ್ಲಿ ಕಾಣುತ್ತದೆ; ಸಾಲನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ ಆ ಏಕಮಾನ ಆರಿಸಿ.',
    help_4: 'ಸಂಖ್ಯೆಗಳ ಟ್ಯಾಬ್‌ನಲ್ಲಿ ಯಾವುದೇ ಪೂರ್ಣ ಸಂಖ್ಯೆ ಬರೆಯಿರಿ: ಭಾರತೀಯ ಮತ್ತು ಅಂತರರಾಷ್ಟ್ರೀಯ ಅಲ್ಪವಿರಾಮ, ಪದಗಳಲ್ಲಿ ಸಂಖ್ಯೆ, ಸ್ಥಾನಬೆಲೆ ಕೋಷ್ಟಕ ಮತ್ತು ವಿಸ್ತೃತ ರೂಪ ನೋಡಿ.',
    help_5: 'ತರಗತಿ ಚಟುವಟಿಕೆ: ರಸಪ್ರಶ್ನೆ ಮೋಡ್ ಆನ್ ಮಾಡಿ “ಯಾವುದಾದರೂ ಸಂಖ್ಯೆ” ಒತ್ತಿ. ತಂಡಗಳು ಆ ಸಂಖ್ಯೆಯನ್ನು ಎರಡೂ ಪದ್ಧತಿಗಳಲ್ಲಿ ಪದಗಳಲ್ಲಿ ಬರೆಯಲಿ; ನಂತರ “ಉತ್ತರ ತೋರಿಸು” ಒತ್ತಿ ಪರಿಶೀಲಿಸಿ.',
    help_6: 'ಅಭ್ಯಾಸ ಟ್ಯಾಬ್: ಸಣ್ಣ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಿಸಿ (ತಪ್ಪಾದರೆ ಹಂತಗಳು ಕಾಣುತ್ತವೆ) ಅಥವಾ 10 ಪ್ರಶ್ನೆಗಳ ವರ್ಕ್‌ಶೀಟ್ ಮುದ್ರಿಸಿ. ಸ್ವಚ್ಛ ಹಾಳೆಗಾಗಿ ಮುದ್ರಿಸಿ, ಸ್ಮಾರ್ಟ್‌ಬೋರ್ಡ್‌ನಲ್ಲಿ ಪೂರ್ಣ ಪರದೆ ಬಳಸಿ.',
    u_ang: 'ಆಂಗ್‌ಸ್ಟ್ರಾಮ್', u_au: 'ಖಗೋಳ ಏಕಮಾನ', u_ly: 'ಜ್ಯೋತಿರ್ವರ್ಷ',
