    hint_same: 'രണ്ട് ഏകകങ്ങളും ഒരേ വലുപ്പമാണ്, അതിനാൽ സംഖ്യ മാറുന്നില്ല.',
    speed_trick_title: '5/18 സൂത്രം',
    speed_trick: '1 km/h = 1000 m ÷ 3600 s = 5/18 m/s. അതിനാൽ km/h → m/s ആക്കാൻ 5/18 കൊണ്ട് ഗുണിക്കുക, m/s → km/h ആക്കാൻ 18/5 കൊണ്ട് ഗുണിക്കുക.',
    temp_formulas_title: 'താപനിലയുടെ സൂത്രവാക്യങ്ങൾ',
    data_note: 'കിലോബൈറ്റ് രണ്ടു തരം: ഫോൺ, പെൻ-ഡ്രൈവ് നിർമാതാക്കൾ 1 KB = 1000 ബൈറ്റ് എന്ന് എണ്ണുന്നു. 1 KiB = 1024 ബൈറ്റിനെ പല സ്കൂൾ പുസ്തകങ്ങളും Windows-ഉം നേരിട്ട് “KB” എന്ന് വിളിക്കുന്നു.',
    area_note: 'ബിഘ, ബിസ്വ, കനാൽ, മർല പോലുള്ള ഭൂമി ഏകകങ്ങൾ ഓരോ സംസ്ഥാനത്തും വ്യത്യസ്ത അളവിലാണ്, അതിനാൽ ഇവിടെ നൽകിയിട്ടില്ല. അവയ്ക്കായി നിങ്ങളുടെ സംസ്ഥാനത്തെ ഭൂരേഖകൾ നോക്കുക.',
    try_title: 'ഒരു ഉദാഹരണം പരീക്ഷിക്കൂ',
    did_you_know: 'നിങ്ങൾക്കറിയാമോ?',
    all_units_title: 'ഇതേ വില എല്ലാ ഏകകങ്ങളിലും',
    all_units_hint: 'ഒരു വരിയിൽ ടാപ്പ് ചെയ്താൽ ആ ഏകകത്തിലേക്ക് മാറും.',
    unit_col: 'ഏകകം', value_col: 'വില',
    note_length: '1 km = 1000 m, 1 m = 100 cm, 1 cm = 10 mm. ക്രിക്കറ്റ് പിച്ചിന് 22 വാര നീളമുണ്ട്, ഏകദേശം 20.12 m.',
    note_mass: '1 ക്വിന്റൽ = 100 kg (ധാന്യ ചന്തകളിൽ ഉപയോഗിക്കുന്നു), 1 ടൺ = 1000 kg. രത്നങ്ങൾ കാരറ്റിൽ (0.2 g) തൂക്കുന്നു; പഴയ തോല ഏകദേശം 11.66 g ആണ്.',
    note_time: '1 മണിക്കൂർ = 60 മിനിറ്റ് = 3600 സെക്കൻഡ്, 1 ദിവസം = 86,400 സെക്കൻഡ്. ഇവിടെ 1 വർഷം 365 ദിവസമായി എടുത്തിരിക്കുന്നു (അധിവർഷത്തിൽ 366 ദിവസം).',
    note_temp: 'വെള്ളം 0 °C (32 °F, 273.15 K) ൽ ഉറയുന്നു, 100 °C (212 °F) ൽ തിളയ്ക്കുന്നു. ശരീരത്തിന്റെ സാധാരണ താപനില ഏകദേശം 37 °C (98.6 °F).',
    note_area: '1 ഹെക്ടർ എന്നാൽ 100 m × 100 m സമചതുരം = 10,000 m², ഏകദേശം 2.47 ഏക്കർ. 1 ഏക്കർ = 100 സെന്റ് = 40 ഗുണ്ട, 1 ഗജം = 1 ചതുരശ്ര വാര.',
