    note_speed: 'വേഗം = ദൂരം ÷ സമയം. 60 km/h വേഗപരിധി ഏകദേശം 16.7 m/s ആണ്. വായുവിൽ ശബ്ദം ഏകദേശം 343 m/s വേഗത്തിൽ സഞ്ചരിക്കുന്നു.',
    note_data: '1 ബൈറ്റ് = 8 ബിറ്റ്. 128 GB പെൻ-ഡ്രൈവ് Windows കമ്പ്യൂട്ടറിൽ ഏകദേശം 119 GB മാത്രം കാണിക്കും; നിർമാതാവ് 1000 കണക്കിലും Windows 1024 കണക്കിലും എണ്ണുന്നു.',
