    help_1: 'എന്ത് മാറ്റണമെന്ന് തിരഞ്ഞെടുത്ത്, രണ്ട് ഏകകങ്ങൾ തിരഞ്ഞെടുത്ത്, ഏതെങ്കിലും പെട്ടിയിൽ സംഖ്യ എഴുതുക. മറ്റേ പെട്ടി ഉടൻ മാറും.',
