    help_5: 'ക്ലാസ് പ്രവർത്തനം: ക്വിസ് മോഡ് ഓണാക്കി “ഏതെങ്കിലും സംഖ്യ” അമർത്തുക. ടീമുകൾ ആ സംഖ്യ രണ്ടു രീതിയിലും വാക്കുകളിൽ എഴുതട്ടെ; പിന്നെ “ഉത്തരം കാണിക്കുക” അമർത്തി പരിശോധിക്കുക.',
